@lru_cache(maxsize=256)
def get_icon_texture(name: str, size: int = 20, color: str = "#FFFFFF") -> Gdk.Texture:
    body = _SVG_PATHS.get(name, _SVG_PATHS["play"])
    svg = (
        f'<svg xmlns="http://www.w3.org/2000/svg" width="{size}" height="{size}" '
        f'viewBox="0 0 24 24" fill="{color}" color="{color}">{body}</svg>'
    ).encode("utf-8")
    return Gdk.Texture.new_from_bytes(GLib.Bytes.new(svg))


@lru_cache(maxsize=8)
def _render_app_icon_texture(size: int) -> Gdk.Texture:
    svg = (
        f'<svg xmlns="http://www.w3.org/2000/svg" width="{size}" height="{size}" viewBox="0 0 128 128">'
        '<defs>'
        '<linearGradient id="bg" x1="0%" y1="0%" x2="100%" y2="100%">'
        '<stop offset="0%" stop-color="#2B2B2B"/><stop offset="100%" stop-color="#0F0F0F"/>'
        '</linearGradient>'
        '<linearGradient id="ring" x1="0%" y1="0%" x2="100%" y2="100%">'
        '<stop offset="0%" stop-color="#F2F2F2"/><stop offset="100%" stop-color="#8C8C8C"/>'
        '</linearGradient>'
        '</defs>'
        '<rect x="4" y="4" width="120" height="120" rx="28" fill="url(#bg)" stroke="#3A3A3A" stroke-width="2"/>'
        '<circle cx="64" cy="64" r="35" fill="none" stroke="url(#ring)" stroke-width="12"/>'
        '<polygon points="57,50 57,78 81,64" fill="#FFFFFF" stroke="#FFFFFF" stroke-width="4" stroke-linejoin="round"/>'
        '</svg>'
    ).encode("utf-8")
    return Gdk.Texture.new_from_bytes(GLib.Bytes.new(svg))


def make_app_icon_image(size: int = 24) -> Gtk.Image:
    """Returns the CERO application vector icon as a Gtk.Image."""
    img = Gtk.Image.new_from_paintable(_render_app_icon_texture(size))
    img.set_pixel_size(size)
    return img


def make_icon_image(name: str, size: int = 20, color: str = "#FFFFFF") -> Gtk.Image:
    img = Gtk.Image.new_from_paintable(get_icon_texture(name, size=size, color=color))
    img.set_pixel_size(size)
    return img


def set_button_svg(btn: Gtk.Button, name: str, size: int = 20, color: str = "#FFFFFF") -> None:
    btn.set_child(make_icon_image(name, size=size, color=color))
